const express = require('express');
const { spawn } = require('child_process');
const { ChartConfig } = require('../models/chartConfig');

const app = express();
app.use(express.json());

app.post('/api/dashboards/render-chart', async (req, res) => {
  if (!req.session || !req.session.userId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { chartConfigId } = req.body;

  // Verify dashboard chart permission
  const config = await ChartConfig.findOne({
    where: {
      id: chartConfigId,
      organizationId: req.session.organizationId
    }
  });

  if (!config) {
    return res.status(403).json({ error: 'Access denied to requested dashboard chart configuration' });
  }

  const worker = spawn('node', ['./workers/renderChart.js', chartConfigId]);

  let imageBuffer = Buffer.alloc(0);
  worker.stdout.on('data', (chunk) => {
    imageBuffer = Buffer.concat([imageBuffer, chunk]);
  });

  worker.on('close', (code) => {
    if (code === 0) {
      res.setHeader('Content-Type', 'image/png');
      res.send(imageBuffer);
    } else {
      res.status(500).json({ error: 'Chart rendering failed' });
    }
  });
});

app.listen(9002);
